"use strict";(self.webpackChunkreact_ui_animate_docs=self.webpackChunkreact_ui_animate_docs||[]).push([[8581],{5610:e=>{e.exports=JSON.parse('{"pluginId":"default","version":"current","label":"Next","banner":"unreleased","badge":true,"noIndex":false,"className":"docs-version-current","isLast":false,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Getting started","href":"/docs/next/getting-started","docId":"getting-started","unlisted":false},{"type":"category","label":"Concept","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"useValue","href":"/docs/next/concept/useValue","docId":"concept/useValue","unlisted":false},{"type":"link","label":"Interpolation","href":"/docs/next/concept/interpolation","docId":"concept/interpolation","unlisted":false},{"type":"link","label":"Mount","href":"/docs/next/concept/use-mount","docId":"concept/use-mount","unlisted":false}]},{"type":"category","label":"Gesture","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Overview","href":"/docs/next/gesture/overview","docId":"gesture/overview","unlisted":false},{"type":"link","label":"useDrag","href":"/docs/next/gesture/useDrag","docId":"gesture/useDrag","unlisted":false},{"type":"link","label":"useMove","href":"/docs/next/gesture/useMove","docId":"gesture/useMove","unlisted":false},{"type":"link","label":"useScroll","href":"/docs/next/gesture/useScroll","docId":"gesture/useScroll","unlisted":false},{"type":"link","label":"useWheel","href":"/docs/next/gesture/useWheel","docId":"gesture/useWheel","unlisted":false}]},{"type":"category","label":"Animation Modifier","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Overview","href":"/docs/next/animation-modifier/overview","docId":"animation-modifier/overview","unlisted":false},{"type":"link","label":"withSpring","href":"/docs/next/animation-modifier/withSpring","docId":"animation-modifier/withSpring","unlisted":false},{"type":"link","label":"withTiming","href":"/docs/next/animation-modifier/withTiming","docId":"animation-modifier/withTiming","unlisted":false},{"type":"link","label":"withDecay","href":"/docs/next/animation-modifier/withDecay","docId":"animation-modifier/withDecay","unlisted":false},{"type":"link","label":"withSequence","href":"/docs/next/animation-modifier/withSequence","docId":"animation-modifier/withSequence","unlisted":false},{"type":"link","label":"withDelay","href":"/docs/next/animation-modifier/withDelay","docId":"animation-modifier/withDelay","unlisted":false},{"type":"link","label":"withLoop","href":"/docs/next/animation-modifier/withLoop","docId":"animation-modifier/withLoop","unlisted":false}]},{"type":"category","label":"Hook","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"useOutsideClick","href":"/docs/next/hooks/useOutsideClick","docId":"hooks/useOutsideClick","unlisted":false}]}]},"docs":{"animation-modifier/overview":{"id":"animation-modifier/overview","title":"Overview","description":"Animation Modifiers are used with the useValue hook that lets you create performant, declarative animations.","sidebar":"tutorialSidebar"},"animation-modifier/withDecay":{"id":"animation-modifier/withDecay","title":"withDecay","description":"The withDecay modifier animates a value by simulating momentum with friction. You typically provide an initial velocity, and the value will coast and gradually slow to a stop. This is particularly useful for implementing flick or throw gestures, or any scenario where you want a natural slowdown effect, similar to a thrown ball gradually losing speed.","sidebar":"tutorialSidebar"},"animation-modifier/withDelay":{"id":"animation-modifier/withDelay","title":"withDelay","description":"The withDelay modifier delays the start of an animation by a specified time in milliseconds. It\'s particularly useful for sequencing or staggering animations.","sidebar":"tutorialSidebar"},"animation-modifier/withLoop":{"id":"animation-modifier/withLoop","title":"withLoop","description":"The withLoop modifier allows you to repeat (loop) an animation a specified number of times or indefinitely. You wrap an existing animation descriptor with withLoop, and it will restart automatically based on the configured options.","sidebar":"tutorialSidebar"},"animation-modifier/withSequence":{"id":"animation-modifier/withSequence","title":"withSequence","description":"The withSequence modifier allows you to chain multiple animations together, executing them one after another in the order they are defined. This is useful for creating complex, multi-step animations where each step needs to be completed before the next begins.","sidebar":"tutorialSidebar"},"animation-modifier/withSpring":{"id":"animation-modifier/withSpring","title":"withSpring","description":"The withSpring modifier animates a value using spring physics, creating natural motion with realistic bounce and overshoot effects.","sidebar":"tutorialSidebar"},"animation-modifier/withTiming":{"id":"animation-modifier/withTiming","title":"withTiming","description":"The withTiming modifier animates a value linearly or with a specified easing function to a given target over a fixed duration. It\'s ideal for simple, predictable transitions like fades or scales, where precise control over the animation\'s timing is crucial.","sidebar":"tutorialSidebar"},"concept/interpolation":{"id":"concept/interpolation","title":"Interpolation","description":"Interpolation is the process of mapping one range of values to another.\\\\","sidebar":"tutorialSidebar"},"concept/use-mount":{"id":"concept/use-mount","title":"Mount","description":"The `` component provides a declarative, animated mounting and unmounting experience for your React components. It smoothly animates values when the component enters or leaves, ideal for transitions, popups, modals, or expandable panels.","sidebar":"tutorialSidebar"},"concept/useValue":{"id":"concept/useValue","title":"useValue","description":"The useValue() function is a powerful hook designed to manage and animate values within your React components without triggering unnecessary re-renders. It behaves similarly to a ref, holding the current animation state internally.","sidebar":"tutorialSidebar"},"gesture/overview":{"id":"gesture/overview","title":"Overview","description":"The react-ui-animate library provides a powerful set of gesture hooks designed to simplify user interaction handling \u2014 whether it\u2019s dragging cards, tracking mouse movement, listening to scrolls, or capturing wheel input for zooming or custom behavior. \\\\","sidebar":"tutorialSidebar"},"gesture/useDrag":{"id":"gesture/useDrag","title":"useDrag","description":"The useDrag hook allows to add drag gesture recognition to any DOM element in a React component. It handles pointer events under the hood, calculates movement, offset, velocity, and exposes a powerful callback-based API for interacting with drag state in real-time.","sidebar":"tutorialSidebar"},"gesture/useMove":{"id":"gesture/useMove","title":"useMove","description":"The useMove hook listens to pointer movements(without needing a press or drag) and provides real-time feedback like movement delta, velocity, and cursor offset. It supports both HTML elements and the window object.","sidebar":"tutorialSidebar"},"gesture/useScroll":{"id":"gesture/useScroll","title":"useScroll","description":"The useScroll hook captures scroll activity on any DOM element or the window. It reports how far you scrolled, how fast, and gives access to the native scroll event.","sidebar":"tutorialSidebar"},"gesture/useWheel":{"id":"gesture/useWheel","title":"useWheel","description":"The useWheel hook listens to wheel gestures on a DOM element or the window, giving you scroll-like movement data with access to deltas, velocity, and raw events \u2014 perfect for zooming, panning, and gesture-driven UIs.","sidebar":"tutorialSidebar"},"getting-started":{"id":"getting-started","title":"Getting started","description":"React UI Animate makes it simple to create smooth, performant animations and interactive gestures in React applications.\\\\","sidebar":"tutorialSidebar"},"hooks/useOutsideClick":{"id":"hooks/useOutsideClick","title":"useOutsideClick","description":"The useOutsideClick hook allows you to detect clicks that occur outside a specific DOM element, triggering a callback function when this happens.\\\\","sidebar":"tutorialSidebar"}}}')}}]);